func (m *Mutation) ResetField(name string) error {
	switch name {
	case FieldAlias:
		m.ResetAlias()
		return nil
	case FieldName:
		m.ResetName()
		return nil
	case FieldDesc:
		m.ResetDesc()
		return nil
	case FieldLabels:
		m.ResetLabels()
		return nil
	case FieldOwnerSession:
		m.ResetOwnerSession()
		return nil
	case FieldRevision:
		m.ResetRevision()
		return nil
	case FieldDateDeleted:
		m.ResetDateDeleted()
		return nil
	case FieldDateUpdated:
		m.ResetDateUpdated()
		return nil
	case FieldDateCreated:
		m.ResetDateCreated()
		return nil
	case FieldContent:
		m.ResetContent()
		return nil
	case FieldClientId:
		m.ResetClientId()
		return nil
	case FieldProjectId:
		m.ResetProjectId()
		return nil
	}
	return fmt.Errorf("unknown Memory field %s", name)
}

// AddedEdges returns all edge names that were set/added in this mutation.
func (m *Mutation) AddedEdges() []string {
	edges := make([]string, 0, 1)
	if m.project != nil {
		edges = append(edges, EdgeProject)
	}
	return edges
}

// AddedIds returns all Ids (to other nodes) that were added for the given edge
// name in this mutation.
func (m *Mutation) AddedIds(name string) []ent.Value {
	switch name {
	case EdgeProject:
		if id := m.project; id != nil {
			return []ent.Value{*id}
		}
	}
	return nil
}

// RemovedEdges returns all edge names that were removed in this mutation.
func (m *Mutation) RemovedEdges() []string {
	edges := make([]string, 0, 1)
	return edges
}

// RemovedIds returns all Ids (to other nodes) that were removed for the edge with
// the given name in this mutation.
func (m *Mutation) RemovedIds(name string) []ent.Value {
	return nil
}

// ClearedEdges returns all edge names that were cleared in this mutation.
func (m *Mutation) ClearedEdges() []string {
	edges := make([]string, 0, 1)
	if m.clearedproject {
		edges = append(edges, EdgeProject)
	}
	return edges
}

// EdgeCleared returns a boolean which indicates if the edge with the given name
// was cleared in this mutation.
func (m *Mutation) EdgeCleared(name string) bool {
	switch name {
	case EdgeProject:
		return m.clearedproject
	}
	return false
}

// ClearEdge clears the value of the edge with the given name. It returns an error
// if that edge is not defined in the schema.
func (m *Mutation) ClearEdge(name string) error {
	switch name {
	case EdgeProject:
		m.ClearProject()
		return nil
	}
	return fmt.Errorf("unknown Memory unique edge %s", name)
}

// ResetEdge resets all changes to the edge with the given name in this mutation.
// It returns an error if the edge is not defined in the schema.
func (m *Mutation) ResetEdge(name string) error {
	switch name {
	case EdgeProject:
		m.ResetProject()
		return nil
	}
	return fmt.Errorf("unknown Memory edge %s", name)
}
